"""Load the real-play snapshot fixtures (generated by fixtures_gen, checked by
test_fixture_provenance.py) as engine games."""

from __future__ import annotations

import json
from pathlib import Path

from game.game import Game
from game.snapshot import from_snapshot

SNAPSHOT_DIR = (
    Path(__file__).resolve().parents[3] / "frontend/tests/e2e/fixtures/snapshots"
)


def load_fixture(name: str) -> Game:
    data = json.loads((SNAPSHOT_DIR / f"{name}.json").read_text())
    return from_snapshot(data["snapshot"])
